struct Parameters { strength: f32, _pad0: f32, _pad1: f32, _pad2: f32, }
@group(0) @binding(0) var<uniform> parameters: Parameters;
@group(0) @binding(1) var output: texture_storage_2d<rgba16float, write>;
@group(0) @binding(2) var input: texture_2d<f32>;
@compute @workgroup_size(8, 8, 1)
fn height_to_normal(@builtin(global_invocation_id) id: vec3<u32>) {
    let size = textureDimensions(output);
    if any(id.xy >= size) { return; }
    let left = vec2<u32>((id.x + size.x - 1u) % size.x, id.y);
    let right = vec2<u32>((id.x + 1u) % size.x, id.y);
    let up = vec2<u32>(id.x, (id.y + size.y - 1u) % size.y);
    let down = vec2<u32>(id.x, (id.y + 1u) % size.y);
    let du = (textureLoad(input, vec2<i32>(right), 0).r - textureLoad(input, vec2<i32>(left), 0).r) * (0.5 * f32(size.x));
    let dv = (textureLoad(input, vec2<i32>(down), 0).r - textureLoad(input, vec2<i32>(up), 0).r) * (0.5 * f32(size.y));
    let normal = normalize(vec3<f32>(-du * parameters.strength, dv * parameters.strength, 1.0));
    textureStore(output, vec2<i32>(id.xy), mixture_half4(vec4<f32>(normal * 0.5 + vec3<f32>(0.5), 1.0)));
}

// Round f32 to binary16, ties to even, while retaining an exactly representable
// f32 result. Texture storage then cannot choose a different rounding direction.
// Integer rounding avoids backend-dependent quantizeToF16 implementations.
fn mixture_half(value: f32) -> f32 {
    let bits = bitcast<u32>(value);
    let sign = bits & 0x80000000u;
    let magnitude = bits & 0x7fffffffu;
    if magnitude >= 0x7f800000u { return value; } // Preserve invalid data for readback diagnostics.
    if magnitude >= 0x38800000u {
        let rounded = (magnitude + 0xfffu + ((magnitude >> 13u) & 1u)) & 0xffffe000u;
        return bitcast<f32>(sign | rounded);
    }
    if magnitude < 0x33000000u { return bitcast<f32>(sign); }
    // Half subnormals are integer multiples of 2^-24. Here shift is 14..24.
    let shift = 126u - (magnitude >> 23u);
    let mantissa = (magnitude & 0x7fffffu) | 0x800000u;
    let rounded = (mantissa + (1u << (shift - 1u)) - 1u + ((mantissa >> shift) & 1u)) >> shift;
    return bitcast<f32>(sign | bitcast<u32>(f32(rounded) * (1.0 / 16777216.0)));
}
fn mixture_half4(value: vec4<f32>) -> vec4<f32> {
    return vec4<f32>(mixture_half(value.x), mixture_half(value.y), mixture_half(value.z), mixture_half(value.w));
}

struct Parameters {
    input_min: f32, input_max: f32, gamma: f32, output_min: f32,
    output_max: f32, _pad0: f32, _pad1: f32, _pad2: f32,
}
@group(0) @binding(0) var<uniform> parameters: Parameters;
@group(0) @binding(1) var output: texture_storage_2d<rgba16float, write>;
@group(0) @binding(2) var input: texture_2d<f32>;
@compute @workgroup_size(8, 8, 1)
fn levels(@builtin(global_invocation_id) id: vec3<u32>) {
    if any(id.xy >= textureDimensions(output)) { return; }
    let value = textureLoad(input, vec2<i32>(id.xy), 0).r;
    var result: f32;
    // Exact endpoints also avoid evaluating pow(0, x) and divisions in tiny
    // intervals containing no representable rgba16float input between bounds.
    if value <= parameters.input_min {
        result = parameters.output_min;
    } else if value >= parameters.input_max {
        result = parameters.output_max;
    } else {
        let t = clamp((value - parameters.input_min) / (parameters.input_max - parameters.input_min), 0.0, 1.0);
        result = parameters.output_min + pow(t, 1.0 / parameters.gamma) * (parameters.output_max - parameters.output_min);
    }
    textureStore(output, vec2<i32>(id.xy), mixture_half4(vec4<f32>(result, 0.0, 0.0, 1.0)));
}
